public struct UnitStats
{
    public int Hp;
    public int Shield;
}

public static class DamageSystem
{
    // The shield absorbs damage first; the rest is taken from Hp (never below 0).
    private static void ApplyDamage(UnitStats target, int damage)
    {
        int absorbed = Math.Min(target.Shield, damage);
        target.Shield -= absorbed;
        target.Hp = Math.Max(0, target.Hp - (damage - absorbed));
    }

    /// <summary>Applies the same area damage (0 or more) to every unit in the array.</summary>
    public static void ApplyAreaDamage(UnitStats[] units, int damage)
    {
        for (int i = 0; i < units.Length; i++)
        {
            UnitStats unit = units[i];
            ApplyDamage(unit, damage);
        }
    }
}

