using System;
using System.Collections.Generic;

public enum DamageType { Physical, Fire, Ice, Poison }

public interface IDamageModifier
{
    int Modify(int damage);
}

/// <summary>Flat reduction: damage - Armor, but a hit always deals at least 1.</summary>
public struct ArmorModifier : IDamageModifier
{
    public int Armor;
    public ArmorModifier(int armor) { Armor = armor; }
    public int Modify(int damage) { return Math.Max(1, damage - Armor); }
}

/// <summary>Percent reduction: damage * (100 - Percent) / 100 (integer division).</summary>
public struct ResistModifier : IDamageModifier
{
    public int Percent;
    public ResistModifier(int percent) { Percent = percent; }
    public int Modify(int damage) { return damage * (100 - Percent) / 100; }
}

/// <summary>Debug log. Off in release builds; QA turns it on to trace combat.</summary>
public static class CombatLog
{
    public static bool Enabled;
    public static readonly List<string> Lines = new List<string>();

    // Callers must check Enabled BEFORE calling: the object[] and the boxed
    // arguments are created at the call site, before this method can return early.
    public static void Debug(string format, params object[] args)
    {
        if (!Enabled) return;
        Lines.Add(string.Format(format, args));
    }
}

public sealed class DamageTracker
{
    // Keyed by the enum type itself. A Dictionary<Enum, int> converts every key
    // to System.Enum, which is a boxing conversion.
    private readonly Dictionary<DamageType, int> _totals = new Dictionary<DamageType, int>();

    // Generic + constraint: T is the struct type itself, so no interface-typed
    // value is created and nothing is boxed.
    private static int Apply<TModifier>(TModifier modifier, int damage)
        where TModifier : struct, IDamageModifier
    {
        return modifier.Modify(damage);
    }

    /// <summary>Armor is applied first, then resistance.</summary>
    public static int Resolve(int rawDamage, ArmorModifier armor, ResistModifier resist)
    {
        int afterArmor = Apply(armor, rawDamage);
        return Apply(resist, afterArmor);
    }

    public void AddDamage(DamageType type, int amount)
    {
        _totals.TryGetValue(type, out int total);
        _totals[type] = total + amount;
    }

    public int GetTotal(DamageType type)
    {
        return _totals.TryGetValue(type, out int total) ? total : 0;
    }

    /// <summary>Resolves one hit, adds it to the per-type total, logs it, and returns the final damage.</summary>
    public int RecordHit(int targetId, DamageType type, int rawDamage, ArmorModifier armor, ResistModifier resist)
    {
        int final = Resolve(rawDamage, armor, resist);
        AddDamage(type, final);
        if (CombatLog.Enabled)
        {
            CombatLog.Debug("target {0} took {1} {2}", targetId, final, type);
        }
        return final;
    }
}

