        catch (System.Exception e) { reason = "예외 발생: " + e.GetType().Name; }
        finally { CombatLog.Enabled = false; CombatLog.Lines.Clear(); }
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    private static int RefResolve(int raw, int armor, int resist)
    {
        int afterArmor = System.Math.Max(1, raw - armor);
        return afterArmor * (100 - resist) / 100;
    }

    private static string CheckResolve(int raw, int armor, int resist, int expected)
    {
        int got = DamageTracker.Resolve(raw, new ArmorModifier(armor), new ResistModifier(resist));
        return got == expected ? null : "Resolve(피해 " + raw + ", 방어 " + armor + ", 저항 " + resist + "%): 기대 " + expected + ", 결과 " + got;
    }

    // Runs `body` 300 times and returns the bytes allocated by the last 150 runs.
    private static long Measure(System.Action body)
    {
        long allocated = 0;
        for (int round = 0; round < 300; round++)
        {
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            body();
            long after = System.GC.GetAllocatedBytesForCurrentThread();
            if (round >= 150) allocated += after - before;
        }
        return allocated;
    }

    private static long _sink;

    public static void Main()
    {
        Run("resolve-armor-then-resist", () =>
            CheckResolve(100, 30, 50, 35) ?? CheckResolve(100, 0, 0, 100) ?? CheckResolve(5, 10, 0, 1)
            ?? CheckResolve(5, 10, 50, 0) ?? CheckResolve(200, 20, 100, 0) ?? CheckResolve(1000, 1, 25, 749));
        Run("totals-per-type", () =>
        {
            var a = new DamageTracker(); var b = new DamageTracker();
            if (a.GetTotal(DamageType.Ice) != 0) return "기록이 없는 속성의 GetTotal: 기대 0, 결과 " + a.GetTotal(DamageType.Ice);
            a.AddDamage(DamageType.Fire, 10); a.AddDamage(DamageType.Fire, 5); a.AddDamage(DamageType.Poison, 7); a.AddDamage(DamageType.Physical, 1);
            b.AddDamage(DamageType.Fire, 100);
            string got = a.GetTotal(DamageType.Physical) + "/" + a.GetTotal(DamageType.Fire) + "/" + a.GetTotal(DamageType.Ice) + "/" + a.GetTotal(DamageType.Poison) + " " + b.GetTotal(DamageType.Fire);
            return got == "1/15/0/7 100" ? null : "속성별 합계(물리/화염/냉기/독, 다른 트래커의 화염): 기대 1/15/0/7 100, 결과 " + got;
        });
        Run("record-hit-returns-and-accumulates", () =>
        {
            var t = new DamageTracker();
            int r1 = t.RecordHit(1, DamageType.Fire, 100, new ArmorModifier(30), new ResistModifier(50));
            int r2 = t.RecordHit(2, DamageType.Fire, 5, new ArmorModifier(10), new ResistModifier(0));
            int r3 = t.RecordHit(1, DamageType.Ice, 40, new ArmorModifier(0), new ResistModifier(25));
            string got = r1 + "," + r2 + "," + r3 + " " + t.GetTotal(DamageType.Fire) + "/" + t.GetTotal(DamageType.Ice);
            return got == "35,1,30 36/30" ? null : "RecordHit 3회의 반환값과 화염/냉기 합계: 기대 35,1,30 36/30, 결과 " + got;
        });
        Run("log-on-and-off", () =>
        {
            var t = new DamageTracker();
            t.RecordHit(5, DamageType.Fire, 100, new ArmorModifier(30), new ResistModifier(50));
            if (CombatLog.Lines.Count != 0) return "로그가 꺼져 있는데 " + CombatLog.Lines.Count + "줄이 기록됨";
            CombatLog.Enabled = true;
            t.RecordHit(7, DamageType.Fire, 100, new ArmorModifier(30), new ResistModifier(50));
            t.RecordHit(12, DamageType.Poison, 5, new ArmorModifier(10), new ResistModifier(0));
            CombatLog.Enabled = false;
            t.RecordHit(9, DamageType.Ice, 10, new ArmorModifier(0), new ResistModifier(0));
            string got = string.Join(" | ", CombatLog.Lines);
            string expected = "target 7 took 35 Fire | target 12 took 1 Poison";
            return got == expected ? null : "로그를 켠 동안의 RecordHit 2회만 기록되어야 함: 기대 [" + expected + "], 결과 [" + got + "]";
        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(9173);
            var t = new DamageTracker(); var totals = new int[4];
            for (int i = 0; i < 5000; i++)
            {
                int type = rng.Next(4), raw = rng.Next(1, 5000), armor = rng.Next(0, 300), resist = rng.Next(0, 101);
                int expected = RefResolve(raw, armor, resist);
                int got = t.RecordHit(i, (DamageType)type, raw, new ArmorModifier(armor), new ResistModifier(resist));
                if (got != expected) return "RecordHit(피해 " + raw + ", 방어 " + armor + ", 저항 " + resist + "%): 기대 " + expected + ", 결과 " + got;
                totals[type] += expected;
            }
            for (int type = 0; type < 4; type++)
                if (t.GetTotal((DamageType)type) != totals[type]) return (DamageType)type + " 합계: 기대 " + totals[type] + ", 결과 " + t.GetTotal((DamageType)type);
            return null;
        });
        Run("zero-alloc-resolve", () =>
        {
            long bytes = Measure(() =>
            {
                long sum = 0;
                for (int i = 0; i < 200; i++) sum += DamageTracker.Resolve(1000 + i * 37, new ArmorModifier(i * 3), new ResistModifier(i % 90));
                _sink += sum;
            });
            return bytes == 0 ? null : "Resolve 30,000회 구간에서 " + bytes + " B가 할당됨";
        });
        Run("zero-alloc-totals", () =>
        {
            var t = new DamageTracker();
            for (int type = 0; type < 4; type++) t.AddDamage((DamageType)type, 1);
            long bytes = Measure(() =>
            {
                long sum = 0;
                for (int i = 0; i < 200; i++) { t.AddDamage((DamageType)(i & 3), i); sum += t.GetTotal((DamageType)((i + 1) & 3)); }
                _sink += sum;
            });
            return bytes == 0 ? null : "AddDamage + GetTotal 30,000회 구간에서 " + bytes + " B가 할당됨";
        });
        Run("zero-alloc-record-hit-log-off", () =>
        {
            var t = new DamageTracker();
            for (int type = 0; type < 4; type++) t.AddDamage((DamageType)type, 1);
            long bytes = Measure(() =>
            {
                long sum = 0;
                for (int i = 0; i < 200; i++) sum += t.RecordHit(100000 + i * 7919, (DamageType)(i & 3), 1000 + i * 37, new ArmorModifier(i * 3), new ResistModifier(i % 90));
                _sink += sum;
            });
            if (CombatLog.Lines.Count != 0) return "로그가 꺼져 있는데 줄이 기록됨";
            return bytes == 0 ? null : "로그가 꺼진 RecordHit 30,000회 구간에서 " + bytes + " B가 할당됨";
        });
    }
}

