using System;
using System.Globalization;

public static class SaveParser
{
    /// <summary>
    /// Parses "x,y,z" (for example "12.5,-3,0.25") into three floats.
    /// Returns false, with x, y, z set to 0, unless text is exactly three numbers separated by commas.
    /// Numbers always use '.' as the decimal point, whatever the device language is.
    /// </summary>
    public static bool TryParsePosition(string text, out float x, out float y, out float z)
    {
        x = 0f; y = 0f; z = 0f;
        if (text == null) return false;

        string[] parts = text.Split(',');          // allocates an array and one string per field
        if (parts.Length != 3) return false;

        if (!float.TryParse(parts[0], NumberStyles.Float, CultureInfo.InvariantCulture, out float px)) return false;
        if (!float.TryParse(parts[1], NumberStyles.Float, CultureInfo.InvariantCulture, out float py)) return false;
        if (!float.TryParse(parts[2], NumberStyles.Float, CultureInfo.InvariantCulture, out float pz)) return false;

        x = px; y = py; z = pz;
        return true;
    }
}

