using System;
using System.Globalization;

public static class SaveParser
{
    /// <summary>
    /// Parses exactly destination.Length comma-separated floats from text ("12.5,-3,0.25").
    /// Returns false if there are too few or too many fields or a field is not a number.
    /// Allocates nothing: fields are sliced out of the original characters.
    /// When it returns false, the contents of destination are unspecified.
    /// </summary>
    public static bool TryParseFloats(ReadOnlySpan<char> text, Span<float> destination)
    {
        ReadOnlySpan<char> rest = text;
        for (int i = 0; i < destination.Length; i++)
        {
            bool isLast = i == destination.Length - 1;
            int comma = rest.IndexOf(',');

            ReadOnlySpan<char> field;
            if (isLast)
            {
                if (comma >= 0) return false;      // more fields than expected
                field = rest;
            }
            else
            {
                if (comma < 0) return false;       // fewer fields than expected
                field = rest.Slice(0, comma);      // a view, not a new string
                rest = rest.Slice(comma + 1);
            }

            // InvariantCulture: '.' is the decimal point on every device, whatever its language is.
            if (!float.TryParse(field, NumberStyles.Float, CultureInfo.InvariantCulture, out destination[i]))
                return false;
        }
        return true;
    }

    /// <summary>Parses "x,y,z". On failure returns false and sets x, y, z to 0.</summary>
    public static bool TryParsePosition(string text, out float x, out float y, out float z)
    {
        x = 0f; y = 0f; z = 0f;
        if (text == null) return false;

        Span<float> values = stackalloc float[3];   // 12 bytes on the stack, gone when this method returns
        if (!TryParseFloats(text.AsSpan(), values)) return false;

        x = values[0]; y = values[1]; z = values[2];
        return true;
    }
}

