using System;
using System.Threading;
using System.Threading.Tasks;

/// <summary>Server-side failure (maintenance, discontinued item...). Its Message is shown to the player as is.</summary>
public sealed class ShopApiException : Exception
{
    public ShopApiException(string message) : base(message) { }
}

/// <summary>
/// Shop server. Responses arrive on a later frame.
/// If ct is canceled before the response arrives, the returned task ends Canceled.
/// </summary>
public interface IShopApi
{
    Task<int[]> GetPricesAsync(CancellationToken ct);
    Task<string> GetDetailAsync(int itemId, CancellationToken ct);
}

/// <summary>Shop UI. Like Unity UI, it may only be called on the main (frame) thread.</summary>
public interface IShopView
{
    void ShowLoading();
    void ShowPrices(int[] prices);
    void ShowDetail(int itemId, string text);
    void ShowError(string message);
}

public sealed class ShopScreen
{
    private readonly IShopApi _api;
    private readonly IShopView _view;

    // Canceled by Close(): every request of this screen hangs off this token.
    private readonly CancellationTokenSource _lifetime = new CancellationTokenSource();
    // Canceled when another item is selected (and, being linked, when the screen closes).
    private CancellationTokenSource _selection;

    public ShopScreen(IShopApi api, IShopView view)
    {
        _api = api;
        _view = view;
    }

    /// <summary>Called on the main thread when the shop opens.</summary>
    public void Open()
    {
        if (_lifetime.IsCancellationRequested) return;
        _view.ShowLoading();
        // Start the request and return to the frame loop. LoadPricesAsync handles all of its
        // exceptions itself, so the discarded task can never fault unobserved.
        _ = LoadPricesAsync(_lifetime.Token);
    }

    /// <summary>Called on the main thread when the player taps an item.</summary>
    public void Select(int itemId)
    {
        if (_lifetime.IsCancellationRequested) return;
        if (_selection != null)
        {
            _selection.Cancel();      // tell the server the old request is no longer needed
            _selection.Dispose();     // also removes its registration on _lifetime
        }
        _selection = CancellationTokenSource.CreateLinkedTokenSource(_lifetime.Token);
        _ = LoadDetailAsync(itemId, _selection.Token);
    }

    /// <summary>Called on the main thread when the shop closes.</summary>
    public void Close()
    {
        if (_lifetime.IsCancellationRequested) return;
        _lifetime.Cancel();           // cancels the price request and the linked selection token
        _selection?.Dispose();
        _selection = null;
    }

    private async Task LoadPricesAsync(CancellationToken ct)
    {
        try
        {
            int[] prices = await _api.GetPricesAsync(ct);
            if (ct.IsCancellationRequested) return;   // closed after the response had already arrived
            _view.ShowPrices(prices);
        }
        catch (Exception e)
        {
            // A canceled request is not an error, and a closed screen shows nothing.
            if (!ct.IsCancellationRequested) _view.ShowError(e.Message);
        }
    }

    private async Task LoadDetailAsync(int itemId, CancellationToken ct)
    {
        try
        {
            string text = await _api.GetDetailAsync(itemId, ct);
            // Cancellation is cooperative: the response may have arrived just before another
            // item was selected, with its continuation already queued for this frame.
            if (ct.IsCancellationRequested) return;
            _view.ShowDetail(itemId, text);
        }
        catch (Exception e)
        {
            if (!ct.IsCancellationRequested) _view.ShowError(e.Message);
        }
    }
}

