// ===== hidden judge =====
// The game's main thread is modelled as a dedicated thread with a single-threaded
// SynchronizationContext: posted continuations run only when the loop runs a frame.
// Server responses complete with RunContinuationsAsynchronously, so the code after
// an await runs on the next frame, as with Unity's main-thread context.
public static class __Judge
{
    sealed class FrameLoop : System.Threading.SynchronizationContext
    {
        readonly System.Collections.Generic.Queue<System.Action> _queue = new System.Collections.Generic.Queue<System.Action>();
        public string Escaped;
        public override void Post(System.Threading.SendOrPostCallback d, object state) { lock (_queue) _queue.Enqueue(() => d(state)); }
        public override void Send(System.Threading.SendOrPostCallback d, object state) { throw new System.NotSupportedException("Send"); }
        public override System.Threading.SynchronizationContext CreateCopy() { return this; }
        public void RunFrame()
        {
            for (int guard = 0; guard < 100000; guard++)
            {
                System.Action next;
                lock (_queue) { if (_queue.Count == 0) return; next = _queue.Dequeue(); }
                try { next(); }
                catch (System.Exception e) { if (Escaped == null) Escaped = e.GetType().Name + ": " + e.Message; }
            }
        }
    }

    sealed class Req<T> { public int ItemId; public System.Threading.CancellationToken Token; public System.Threading.Tasks.TaskCompletionSource<T> Tcs; }

    sealed class FakeApi : IShopApi
    {
        public readonly System.Collections.Generic.List<Req<int[]>> Prices = new System.Collections.Generic.List<Req<int[]>>();
        public readonly System.Collections.Generic.List<Req<string>> Details = new System.Collections.Generic.List<Req<string>>();
        public System.Exception PricesFailNow;
        public System.Threading.Tasks.Task<int[]> GetPricesAsync(System.Threading.CancellationToken ct)
        {
            if (PricesFailNow != null) return System.Threading.Tasks.Task.FromException<int[]>(PricesFailNow);
            return Add(Prices, -1, ct).Tcs.Task;
        }
        public System.Threading.Tasks.Task<string> GetDetailAsync(int itemId, System.Threading.CancellationToken ct) { return Add(Details, itemId, ct).Tcs.Task; }
        static Req<T> Add<T>(System.Collections.Generic.List<Req<T>> list, int id, System.Threading.CancellationToken ct)
        {
            var r = new Req<T> { ItemId = id, Token = ct, Tcs = new System.Threading.Tasks.TaskCompletionSource<T>(System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously) };
            lock (list) list.Add(r);
            if (ct.CanBeCanceled) ct.Register(() => r.Tcs.TrySetCanceled(ct));
            return r;
        }
    }

    sealed class FakeView : IShopView
    {
        public readonly System.Collections.Generic.List<string> Log = new System.Collections.Generic.List<string>();
        public int LoopThread = System.Environment.CurrentManagedThreadId;
        public bool Closed;
        public string Violation;
        void Rec(string s)
        {
            if (System.Environment.CurrentManagedThreadId != LoopThread && Violation == null) Violation = "메인(프레임) 스레드가 아닌 곳에서 view 호출: " + s;
            if (Closed && Violation == null) Violation = "Close 뒤에 view 호출: " + s;
            lock (Log) Log.Add(s);
        }
        public string Text() { lock (Log) return string.Join(" | ", Log); }
        public void ShowLoading() { Rec("Loading"); }
        public void ShowPrices(int[] prices) { Rec("Prices " + string.Join(",", prices)); }
        public void ShowDetail(int itemId, string text) { Rec("Detail " + itemId + " " + text); }
        public void ShowError(string message) { Rec("Error " + message); }
    }

    sealed class Rig { public FakeApi Api = new FakeApi(); public FakeView View = new FakeView(); public ShopScreen Screen; public Rig() { Screen = new ShopScreen(Api, View); } }

    sealed class Env
    {
        public FrameLoop Loop = new FrameLoop();
        public System.Collections.Generic.List<Rig> Rigs = new System.Collections.Generic.List<Rig>();
        public Rig Make() { var r = new Rig(); Rigs.Add(r); return r; }
        public void Frame() { Loop.RunFrame(); }
        public string Check()
        {
            foreach (var r in Rigs) if (r.View.Violation != null) return r.View.Violation;
            return Loop.Escaped == null ? null : "처리되지 않은 예외가 프레임 루프까지 올라옴: " + Loop.Escaped;
        }
    }

    static string Expect(Rig r, string expected, string what)
    {
        string got = r.View.Text();
        return got == expected ? null : what + ": 기대 [" + expected + "], 결과 [" + got + "]";
    }

    static void Run(string id, System.Func<Env, string> body)
    {
        string result = null;
        var thread = new System.Threading.Thread(() =>
        {
            var env = new Env();
            System.Threading.SynchronizationContext.SetSynchronizationContext(env.Loop);
            try { result = body(env); if (result == null) result = env.Check(); }
            catch (System.Exception e) { result = "예외 발생: " + e.GetType().Name + " (" + e.Message + ")"; }
        });
        thread.IsBackground = true;
        thread.Start();
        if (!thread.Join(2000)) { System.Console.WriteLine("[FAIL] " + id + " :: 2초 안에 끝나지 않음: 메인(프레임) 스레드가 막혔습니다"); return; }
        System.Console.WriteLine(result == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + result);
    }

    public static void Main()
    {
        Run("open-returns-immediately", env =>
        {
            var r = env.Make();
            r.Screen.Open();
            if (r.Api.Prices.Count != 1) return "Open이 가격 요청을 1번 보내야 함 (실제 " + r.Api.Prices.Count + "번)";
            env.Frame();
            string e = Expect(r, "Loading", "응답 전");
            if (e != null) return e;
            r.Api.Prices[0].Tcs.SetResult(new[] { 100, 250, 990 });
            env.Frame();
            return Expect(r, "Loading | Prices 100,250,990", "가격 응답 후");
        });

        Run("open-failure-shows-error", env =>
        {
            var r = env.Make();
            r.Api.PricesFailNow = new ShopApiException("서버 점검 중");
            try { r.Screen.Open(); }
            catch (System.Exception ex) { return "가격 요청이 실패하자 Open이 예외를 밖으로 던짐: " + ex.GetType().Name; }
            env.Frame();
            string e = Expect(r, "Loading | Error 서버 점검 중", "즉시 실패한 가격 요청");
            if (e != null) return e;
            var r2 = env.Make();
            r2.Screen.Open();
            env.Frame();
            r2.Api.Prices[0].Tcs.SetException(new ShopApiException("가격표 오류"));
            env.Frame();
            return Expect(r2, "Loading | Error 가격표 오류", "다음 프레임에 실패한 가격 요청");
        });

        Run("detail-error-shown", env =>
        {
            var r = env.Make();
            r.Screen.Select(7);
            env.Frame();
            r.Api.Details[0].Tcs.SetException(new ShopApiException("판매 종료된 아이템"));
            env.Frame();
            return Expect(r, "Error 판매 종료된 아이템", "Select(7)의 요청이 실패한 뒤");
        });

        Run("latest-selection-wins", env =>
        {
            var r = env.Make();
            r.Screen.Select(1);
            r.Screen.Select(2);
            if (r.Api.Details.Count != 2) return "Select 두 번에 상세 요청이 2개여야 함 (실제 " + r.Api.Details.Count + "개)";
            if (!r.Api.Details[0].Token.IsCancellationRequested) return "아이템 2를 고른 뒤에도 아이템 1 요청의 토큰이 취소되지 않음";
            if (r.Api.Details[1].Token.IsCancellationRequested) return "방금 고른 아이템 2 요청의 토큰이 이미 취소됨";
            r.Api.Details[1].Tcs.TrySetResult("빙결의 지팡이");
            r.Api.Details[0].Tcs.TrySetResult("화염의 검");
            env.Frame();
            return Expect(r, "Detail 2 빙결의 지팡이", "1, 2를 차례로 고르고 응답이 2, 1 순서로 온 뒤");
        });

        Run("stale-response-dropped", env =>
        {
            var r = env.Make();
            r.Screen.Select(1);
            r.Api.Details[0].Tcs.SetResult("화염의 검");      // arrived; its continuation waits for the next frame
            r.Screen.Select(2);                                // the player taps another item first
            env.Frame();
            string e = Expect(r, "", "아이템 1의 응답이 도착한 직후(처리 전) 아이템 2를 고른 뒤");
            if (e != null) return e;
            r.Api.Details[1].Tcs.SetResult("빙결의 지팡이");
            env.Frame();
            r.Screen.Select(3);
            r.Api.Details[2].Tcs.SetException(new ShopApiException("판매 종료된 아이템"));
            r.Screen.Select(4);
            env.Frame();
            return Expect(r, "Detail 2 빙결의 지팡이", "이전 선택의 결과·오류는 표시하지 않아야 함");
        });

        Run("close-cancels-pending", env =>
        {
            var r = env.Make();
            r.Screen.Select(5);
            env.Frame();
            r.Screen.Close();
            r.View.Closed = true;
            if (!r.Api.Details[0].Token.IsCancellationRequested) return "Close 뒤에도 대기 중인 상세 요청의 토큰이 취소되지 않음";
            r.Api.Details[0].Tcs.TrySetException(new ShopApiException("늦게 온 오류"));
            env.Frame();
            r.Screen.Select(6);
            env.Frame();
            foreach (var d in r.Api.Details) d.Tcs.TrySetResult("닫힌 뒤의 응답");
            env.Frame();
            var r2 = env.Make();
            r2.Screen.Open();
            env.Frame();
            r2.Screen.Close();
            r2.View.Closed = true;
            if (!r2.Api.Prices[0].Token.IsCancellationRequested) return "Close 뒤에도 대기 중인 가격 요청의 토큰이 취소되지 않음";
            r2.Api.Prices[0].Tcs.TrySetResult(new[] { 1 });
            env.Frame();
            return null;
        });

        Run("random-vs-model", env =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 40; round++)
            {
                var r = env.Make();
                var expected = new System.Collections.Generic.List<string>();
                var arrived = new System.Collections.Generic.List<(Req<string> req, string line)>();
                Req<string> latest = null;
                int nextId = 1;
                for (int step = 0; step < 30; step++)
                {
                    int op = rng.Next(10);
                    if (op < 4)
                    {
                        int before = r.Api.Details.Count;
                        r.Screen.Select(nextId++);
                        if (r.Api.Details.Count != before + 1) return "Select 한 번에 상세 요청이 1개 생겨야 함";
                        latest = r.Api.Details[before];
                    }
                    else if (op < 7 && r.Api.Details.Count > 0)
                    {
                        var req = r.Api.Details[rng.Next(r.Api.Details.Count)];
                        bool ok = rng.Next(3) > 0;
                        string text = "item" + req.ItemId + "-" + step;
                        bool set = ok ? req.Tcs.TrySetResult(text) : req.Tcs.TrySetException(new ShopApiException("err" + step));
                        if (set) arrived.Add((req, ok ? "Detail " + req.ItemId + " " + text : "Error err" + step));
                    }
                    else
                    {
                        env.Frame();
                        foreach (var a in arrived) if (a.req == latest) expected.Add(a.line);
                        arrived.Clear();
                    }
                }
                env.Frame();
                foreach (var a in arrived) if (a.req == latest) expected.Add(a.line);
                string e = Expect(r, string.Join(" | ", expected), "무작위 시나리오 " + round);
                if (e != null) return e.Length > 220 ? e.Substring(0, 220) + "..." : e;
            }
            return null;
        });
    }
}

