using System;

/// <summary>Status effect id (burn, freeze, poison...). A small value type that is compared very often.</summary>
public readonly struct StatusId : IEquatable<StatusId>
{
    public readonly int Value;
    public StatusId(int value) { Value = value; }

    public bool Equals(StatusId other) => Value == other.Value;
    public override bool Equals(object obj) => obj is StatusId other && Equals(other);
    public override int GetHashCode() => Value;
    public static bool operator ==(StatusId a, StatusId b) => a.Equals(b);
    public static bool operator !=(StatusId a, StatusId b) => !a.Equals(b);
}

public static class ArrayUtil
{
    /// <summary>
    /// True if value occurs in items (null items: false).
    /// Called every frame for every unit: "is this unit frozen?", "is this tile on the path?".
    /// </summary>
    // struct: T is a non-nullable value type, so items[i] can never be null.
    // IEquatable<T>: items[i].Equals(value) now binds to Equals(T), so value is not boxed.
    public static bool Contains<T>(T[] items, T value) where T : struct, IEquatable<T>
    {
        if (items == null) return false;
        return Contains((ReadOnlySpan<T>)items, value);
    }

    /// <summary>Same check for any contiguous buffer: an array slice, a stackalloc buffer, a List's backing span.</summary>
    public static bool Contains<T>(ReadOnlySpan<T> items, T value) where T : struct, IEquatable<T>
    {
        for (int i = 0; i < items.Length; i++)
        {
            if (items[i].Equals(value)) return true;
        }
        return false;
    }
}

