using System;
using System.Collections.Generic;

/// <summary>Tile coordinate on the battle map. Used as a Dictionary/HashSet key every frame.</summary>
public readonly struct GridPos : IEquatable<GridPos>
{
    public int X { get; }
    public int Y { get; }

    public GridPos(int x, int y)
    {
        X = x;
        Y = y;
    }

    // The one real comparison. Everything else forwards here so the four entry points cannot disagree.
    public bool Equals(GridPos other) => X == other.X && Y == other.Y;

    // Only for callers that hold an object. Generic collections use Equals(GridPos) instead.
    public override bool Equals(object obj) => obj is GridPos other && Equals(other);

    // Same fields as Equals, so equal positions always hash alike. HashCode.Combine mixes the bits,
    // so (1, 2) and (2, 1) or (x, y) and (y, x) do not collide the way x ^ y does.
    // Its seed is random per process: never save these values.
    public override int GetHashCode() => HashCode.Combine(X, Y);

    public static bool operator ==(GridPos a, GridPos b) => a.Equals(b);

    public static bool operator !=(GridPos a, GridPos b) => !a.Equals(b);

    public override string ToString() => "(" + X + ", " + Y + ")";
}

/// <summary>
/// Equality for a world map that wraps around east-west like a globe:
/// column x and column x + Width are the same column. Y does not wrap.
/// </summary>
public sealed class WrapXComparer : IEqualityComparer<GridPos>
{
    /// <summary>width must be greater than 0, otherwise ArgumentOutOfRangeException.</summary>
    public WrapXComparer(int width)
    {
        if (width <= 0) throw new ArgumentOutOfRangeException(nameof(width));
        Width = width;
    }

    public int Width { get; }

    public bool Equals(GridPos a, GridPos b) => Column(a.X) == Column(b.X) && a.Y == b.Y;

    // Hash exactly what Equals compares: the wrapped column, not the raw X.
    public int GetHashCode(GridPos p) => HashCode.Combine(Column(p.X), p.Y);

    // Mathematical modulo: C#'s % keeps the sign of the dividend, so -1 % 100 is -1, not 99.
    private int Column(int x)
    {
        int c = x % Width;
        return c < 0 ? c + Width : c;
    }
}

