// ===== hidden judge =====
public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string reason;
        try { reason = body(); }
        catch (System.Exception e) { reason = "예외 발생: " + e.GetType().Name + " (" + e.Message + ")"; }
        System.Console.WriteLine(reason == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + reason);
    }

    static GridPos P(int x, int y) { return new GridPos(x, y); }

    static string Same(GridPos a, GridPos b, bool expected)
    {
        object boxed = b;
        bool eq = a.Equals(b), eqObj = a.Equals(boxed), op = a == b, neq = a != b;
        if (eq != expected || eqObj != expected || op != expected || neq == expected)
            return a + " 와 " + b + ": 기대 같음=" + expected + ", Equals(GridPos)=" + eq + ", Equals(object)=" + eqObj + ", ==" + op + ", !=" + neq;
        if (expected && a.GetHashCode() != b.GetHashCode()) return a + " 와 " + b + "는 같은데 GetHashCode가 다름";
        return null;
    }

    static long _sink;

    public static void Main()
    {
        Run("equality-members", () =>
        {
            string e = Same(P(3, 4), P(3, 4), true) ?? Same(P(3, 4), P(4, 3), false) ?? Same(P(-7, 0), P(-7, 0), true)
                ?? Same(P(0, -1), P(0, 1), false) ?? Same(P(int.MinValue, int.MaxValue), P(int.MinValue, int.MaxValue), true)
                ?? Same(P(5, 5), P(5, 6), false) ?? Same(default(GridPos), P(0, 0), true);
            if (e != null) return e;
            if (P(1, 2).Equals(null)) return "Equals(null)이 true";
            if (P(1, 2).Equals((object)"(1, 2)")) return "다른 형식(string)과 Equals(object)가 true";
            if (P(1, 2).Equals((object)new System.Tuple<int, int>(1, 2))) return "다른 형식(Tuple)과 Equals(object)가 true";
            return null;
        });

        Run("dictionary-and-hashset", () =>
        {
            var d = new System.Collections.Generic.Dictionary<GridPos, string>();
            d[P(10, -3)] = "성채"; d[P(-10, 3)] = "늪"; d[P(3, -10)] = "숲";
            d[P(10, -3)] = "점령된 성채";
            if (d.Count != 3) return "같은 칸에 다시 대입했는데 키가 늘어남 (Count " + d.Count + ")";
            if (!d.TryGetValue(P(10, -3), out string v) || v != "점령된 성채") return "새로 만든 같은 좌표로 값을 찾지 못함";
            if (d.ContainsKey(P(-3, 10)) || d.ContainsKey(P(10, 3))) return "다른 칸이 키로 잡힘";
            var set = new System.Collections.Generic.HashSet<GridPos>();
            for (int i = 0; i < 3; i++) for (int x = -5; x <= 5; x++) for (int y = -5; y <= 5; y++) set.Add(P(x, y));
            if (set.Count != 121) return "HashSet 중복 제거: 기대 121칸, 결과 " + set.Count;
            if (!set.Remove(P(-5, 5)) || set.Contains(P(-5, 5))) return "HashSet.Remove 뒤에도 남아 있음";
            return null;
        });

        Run("hash-consistent", () =>
        {
            var rng = new System.Random(4242);
            for (int i = 0; i < 20000; i++)
            {
                int x = rng.Next(int.MinValue, int.MaxValue), y = rng.Next(-100000, 100000);
                var a = P(x, y); var b = P(x, y);
                if (a.GetHashCode() != b.GetHashCode()) return a + ": 같은 좌표의 GetHashCode가 다름";
                if (a.GetHashCode() != a.GetHashCode()) return a + ": GetHashCode가 호출마다 다름";
            }
            return null;
        });

        Run("hash-spread", () =>
        {
            var hashes = new System.Collections.Generic.HashSet<int>();
            for (int x = -128; x < 128; x++) for (int y = -128; y < 128; y++) hashes.Add(P(x, y).GetHashCode());
            double pct = hashes.Count * 100.0 / 65536;
            return pct >= 99.0 ? null : "-128~127 범위 65,536칸의 서로 다른 해시 값이 " + hashes.Count + "개(" + pct.ToString("F1") + "%)뿐임 (99% 이상이어야 함)";
        });

        Run("wrap-comparer", () =>
        {
            try { new WrapXComparer(0); return "너비 0에서 예외가 나지 않음"; } catch (System.ArgumentOutOfRangeException) { }
            var c = new WrapXComparer(100);
            if (c.Width != 100) return "Width: 기대 100, 결과 " + c.Width;
            (GridPos a, GridPos b, bool eq)[] cases =
            {
                (P(-1, 5), P(99, 5), true), (P(0, 5), P(100, 5), true), (P(250, -7), P(-50, -7), true), (P(-201, 2), P(99, 2), true),
                (P(3, 5), P(3, 6), false), (P(3, 5), P(4, 5), false), (P(-1, 5), P(1, 5), false), (P(int.MinValue, 0), P(int.MinValue % 100 + 100, 0), true)
            };
            foreach (var t in cases)
            {
                if (c.Equals(t.a, t.b) != t.eq) return "너비 100에서 " + t.a + " 와 " + t.b + ": 기대 같음=" + t.eq;
                if (t.eq && c.GetHashCode(t.a) != c.GetHashCode(t.b)) return "너비 100에서 " + t.a + " 와 " + t.b + "는 같은데 GetHashCode가 다름";
            }
            var d = new System.Collections.Generic.Dictionary<GridPos, int>(c);
            for (int x = -300; x < 300; x++) for (int y = 0; y < 3; y++) d[P(x, y)] = x;
            if (d.Count != 300) return "너비 100 지도에서 x -300~299, y 0~2를 넣었을 때 기대 300칸, 결과 " + d.Count;
            if (!d.TryGetValue(P(-1, 2), out int v) || v != 299) return "(-1, 2)로 (299, 2)에 넣은 값을 찾지 못함";
            return null;
        });

        Run("no-alloc-lookups", () =>
        {
            var d = new System.Collections.Generic.Dictionary<GridPos, int>(4096);
            var set = new System.Collections.Generic.HashSet<GridPos>(4096);
            var w = new System.Collections.Generic.Dictionary<GridPos, int>(4096, new WrapXComparer(5000));
            for (int x = 1000; x < 1040; x++) for (int y = -2000; y < -1960; y++) { var k = P(x, y); d[k] = x ^ y; set.Add(k); w[k] = x + y; }
            long bytes = 0;
            for (int round = 0; round < 4; round++)
            {
                long before = System.GC.GetAllocatedBytesForCurrentThread();
                long sum = 0;
                for (int x = 1000; x < 1040; x++)
                    for (int y = -2000; y < -1960; y++)
                    {
                        var k = P(x, y);
                        if (d.TryGetValue(k, out int v)) sum += v;
                        if (d.ContainsKey(P(x, y + 7777))) sum++;
                        d[k] = v + 1;
                        if (set.Contains(k)) sum++;
                        if (w.TryGetValue(P(x + 5000 * (round + 1), y), out int wv)) sum += wv;
                        if (k == P(x, y) && !(k != P(x, y)) && k.Equals(P(x, y))) sum += k.GetHashCode() & 1;
                    }
                _sink += sum;
                if (round > 0) bytes += System.GC.GetAllocatedBytesForCurrentThread() - before;
            }
            return bytes == 0 ? null : "키 조회·비교 4,800번(3회 측정)에 " + bytes + " B 할당됨 (박싱이나 문자열 생성 없이 비교·해시해야 함)";
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(9001);
            var d = new System.Collections.Generic.Dictionary<GridPos, int>();
            var r = new System.Collections.Generic.Dictionary<long, int>();
            for (int i = 0; i < 30000; i++)
            {
                int x = rng.Next(-40, 40), y = rng.Next(-40, 40), op = rng.Next(4);
                long key = ((long)x << 32) | (uint)y;
                if (op == 0) { d[P(x, y)] = i; r[key] = i; }
                else if (op == 1) { if (d.Remove(P(x, y)) != r.Remove(key)) return "Remove" + P(x, y) + " 결과가 기준과 다름"; }
                else
                {
                    bool f1 = d.TryGetValue(P(x, y), out int v1), f2 = r.TryGetValue(key, out int v2);
                    if (f1 != f2 || v1 != v2) return "TryGetValue" + P(x, y) + ": 기대 " + f2 + "/" + v2 + ", 결과 " + f1 + "/" + v1;
                }
            }
            return d.Count == r.Count ? null : "최종 Count: 기대 " + r.Count + ", 결과 " + d.Count;
        });
    }
}
